#[cfg(test)]
mod audit_support_probe {
    use super::*;
    #[test]
    fn audit_non_grid_interpolated_support_probe() {
        for n in [64,256,1024] {
            for rate in [44100.0,48000.0,96000.0] {
                let mut ir=vec![0.0;3*2*8];
                for m in 0..3 {for ear in 0..2 {ir[(m*2+ear)*8+2+m]=1.0;}}
                let sofa=SofaFile { sample_rate:rate,num_measurements:3,ir_length:8,
                    positions:(0..3).map(|i| sotf_host::sofa::SourcePosition::new(i as f32*30.0,0.0,1.0)).collect(),
                    impulse_responses:ir,convention:"SimpleFreeFieldHRIR".into(),data_sample_rate:Some(rate) };
                let fft=realfft::RealFftPlanner::<f32>::new().plan_fft_forward(n);
                let prepared=prepare_hrtf_spectra(&sofa,n,rate,&fft);
                let (spectrum,_)=interpolate_hrtf_prepared(&[(0,0.0),(1,0.0),(2,0.0)],&[0.5,0.5,0.0],&prepared,n,rate,0.0,15.0,0.0);
                // Independent f64 real IDFT, with real DC/Nyquist as used by the renderer.
                let impulse:Vec<f64>=(0..n).map(|t| {
                    let mut sum=f64::from(spectrum[0].re);
                    for (k,h) in spectrum.iter().enumerate().take(n/2).skip(1) {
                        let phase=2.0*std::f64::consts::PI*k as f64*t as f64/n as f64;
                        sum+=2.0*(f64::from(h.re)*phase.cos()-f64::from(h.im)*phase.sin());
                    }
                    sum+=f64::from(spectrum[n/2].re)*if t%2==0 {1.0}else{-1.0};
                    sum/n as f64
                }).collect();
                let capacity=n-n/4+1;
                let total: f64=impulse.iter().map(|x|x*x).sum();
                let beyond: f64=impulse[capacity..].iter().map(|x|x*x).sum();
                let prefix=(0..n/4-1).map(|i| impulse[(i+n-(n/4-1))%n].abs()).fold(0.0,f64::max);
                println!("INTERPOLATED_SUPPORT fft={n} rate={rate} source_ir=8 admitted_capacity={capacity} beyond_energy_ratio={} maximum_wrapped_prefix={prefix}",beyond/total);
                assert!(beyond/total>0.01,"diagnostic no longer reproduces support defect");
            }
        }
    }
}

